def main() -> int:
    here = Path(__file__).resolve().parent
    if not (here / "backend" / "app").is_dir():
        print("This file must sit in the folder that contains your 'backend' folder.")
        print(f"I looked in: {here}")
        return 1

    front = here / "frontend"
    print(f"Project folder: {here}")
    print(f"{len(FILES)} files will be written to: {front}")
    if front.exists():
        print("Your existing 'frontend' folder will be moved to _backup_before_update first.")
    if "--yes" not in sys.argv and input("\nContinue? [y/N] ").strip().lower() != "y":
        print("Cancelled. Nothing was changed.")
        return 0

    if front.exists():
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        dest = here / "_backup_before_update" / stamp
        dest.mkdir(parents=True, exist_ok=True)
        shutil.move(str(front), str(dest / "frontend"))
        print(f"Old frontend moved to: {dest / 'frontend'}")

    for rel, blob in FILES.items():
        target = here / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(zlib.decompress(base64.b64decode(blob)))
    print(f"Done. {len(FILES)} files written.")

    npm = shutil.which("npm")
    if not npm:
        print("\nNode.js was not found. Install Node 18 or newer from nodejs.org, then run:  cd frontend  and  npm install")
        return 0
    if "--yes" in sys.argv or input("\nRun 'npm install' in the frontend folder now? [Y/n] ").strip().lower() in ("", "y"):
        code = subprocess.call([npm, "install", "--no-audit", "--no-fund"], cwd=str(front))
        if code != 0:
            print("npm install failed. Check your internet connection and run it again inside the frontend folder.")
            return code
    print("\nAll set. Start it with:  cd frontend  then  npm run dev   (backend must be running on port 8000)")
    return 0


if __name__ == "__main__":
    sys.exit(main())